// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListPatients Список пациентов
	// (GET /api/v1/patients)
	ListPatients(ctx context.Context, request ListPatientsRequestObject) (ListPatientsResponseObject, error)
	// CreatePatient Создать пациента
	// (POST /api/v1/patients)
	CreatePatient(ctx context.Context, request CreatePatientRequestObject) (CreatePatientResponseObject, error)
	// DeletePatient Удалить пациента; при наличии ЭМК возвращает 409
	// (DELETE /api/v1/patients/{id})
	DeletePatient(ctx context.Context, request DeletePatientRequestObject) (DeletePatientResponseObject, error)
	// GetPatient Карточка пациента
	// (GET /api/v1/patients/{id})
	GetPatient(ctx context.Context, request GetPatientRequestObject) (GetPatientResponseObject, error)
	// UpdatePatient Полностью обновить пациента
	// (PUT /api/v1/patients/{id})
	UpdatePatient(ctx context.Context, request UpdatePatientRequestObject) (UpdatePatientResponseObject, error)
	// GetPatientRecord Получить единственную ЭМК пациента
	// (GET /api/v1/patients/{id}/record)
	GetPatientRecord(ctx context.Context, request GetPatientRecordRequestObject) (GetPatientRecordResponseObject, error)
	// CreateRecord Создать ЭМК с обязательным автором
	// (POST /api/v1/patients/{id}/record)
	CreateRecord(ctx context.Context, request CreateRecordRequestObject) (CreateRecordResponseObject, error)
	// GetRecord Текущее состояние карты
	// (GET /api/v1/records/{id})
	GetRecord(ctx context.Context, request GetRecordRequestObject) (GetRecordResponseObject, error)
	// SaveRecord Атомарно сохранить команды и историю
	// (POST /api/v1/records/{id}/changes)
	SaveRecord(ctx context.Context, request SaveRecordRequestObject) (SaveRecordResponseObject, error)
	// GetRecordHistory История по порядку событий
	// (GET /api/v1/records/{id}/history)
	GetRecordHistory(ctx context.Context, request GetRecordHistoryRequestObject) (GetRecordHistoryResponseObject, error)
	// GetRecordState Восстановить карту; требуется ровно один из at или version
	// (GET /api/v1/records/{id}/state)
	GetRecordState(ctx context.Context, request GetRecordStateRequestObject) (GetRecordStateResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

